CustomField.formula:
/* LEVEL 0: Current Record is IMGA */
IF(TEXT(IM_Hierarchy_Level__c) == "IM Group (IMGA)", TEXT(Program_Designation__c),

/* LEVEL 1: Parent is IMGA */
IF(Parent.Global_Account__c && TEXT(Parent.IM_Hierarchy_Level__c) == "IM Group (IMGA)",
IF(TEXT(Parent.Program_Designation__c) == "Strategic Account",
/* If Strategic: Only flow Parent's value if this child is North America */
IF(Territory_Region__c == "North America", TEXT(Parent.Program_Designation__c), NULL),
/* If Global Account: Flow Parent's value directly */
IF(TEXT(Parent.Program_Designation__c) == "Global Account", TEXT(Parent.Program_Designation__c), NULL)
),

/* LEVEL 2: Parent is Country Parent */
IF(NOT(ISBLANK(ParentId)) && TEXT(Parent.Parent.IM_Hierarchy_Level__c) == "IM Group (IMGA)", 
TEXT(Parent.Program_Designation__c), 
NULL)
)
)
